insert into public.legal_provisions (
    version_id, provision_key, sequence, heading_path, heading, label, content
)
select
    '21000000-0000-4000-8000-000000000011', item.chave, item.sequencia, item.caminho, item.titulo, item.rotulo, item.conteudo
from jsonb_to_recordset($dados$[{"chave":"art-1","sequencia":1,"caminho":["LEI MARIA DA PENHA","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"TÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 1º","conteudo":"Esta Lei cria mecanismos para coibir e prevenir a violência doméstica e familiar contra a mulher, nos termos do § 8º do art. 226 da Constituição Federal, da Convenção sobre a Eliminação de Todas as Formas de Violência contra a Mulher, da Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher e de outros tratados internacionais ratificados pela República Federativa do Brasil; dispõe sobre a criação dos Juizados de Violência Doméstica e Familiar contra a Mulher; e estabelece medidas de assistência e proteção às mulheres em situação de violência doméstica e familiar."},{"chave":"art-2","sequencia":2,"caminho":["LEI MARIA DA PENHA","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"TÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 2º","conteudo":"Toda mulher, independentemente de classe, raça, etnia, orientação sexual, renda, cultura, nível educacional, idade e religião, goza dos direitos fundamentais inerentes à pessoa humana, sendo-lhe asseguradas as oportunidades e facilidades para viver sem violência, preservar sua saúde física e mental e seu aperfeiçoamento moral, intelectual e social."},{"chave":"art-3","sequencia":3,"caminho":["LEI MARIA DA PENHA","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"TÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 3º","conteudo":"Serão asseguradas às mulheres as condições para o exercício efetivo dos direitos à vida, à segurança, à saúde, à alimentação, à educação, à cultura, à moradia, ao acesso à justiça, ao esporte, ao lazer, ao trabalho, à cidadania, à liberdade, à dignidade, ao respeito e à convivência familiar e comunitária.\n\n§ 1º O poder público desenvolverá políticas que visem garantir os direitos humanos das mulheres no âmbito das relações domésticas e familiares no sentido de resguardá-las de toda forma de negligência, discriminação, exploração, violência, crueldade e opressão.\n\n§ 2º Cabe à família, à sociedade e ao poder público criar as condições necessárias para o efetivo exercício dos direitos enunciados no caput ."},{"chave":"art-4","sequencia":4,"caminho":["LEI MARIA DA PENHA","TÍTULO I — DISPOSIÇÕES PRELIMINARES"],"titulo":"TÍTULO I — DISPOSIÇÕES PRELIMINARES","rotulo":"Art. 4º","conteudo":"Na interpretação desta Lei serão considerados os fins sociais a que ela se destina e, especialmente, as condições peculiares das mulheres em situação de violência doméstica e familiar."},{"chave":"art-5","sequencia":5,"caminho":["LEI MARIA DA PENHA","TÍTULO II — DA VIOLÊNCIA DOMÉSTICA E FAMILIAR CONTRA A MULHER","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 5º","conteudo":"Para os efeitos desta Lei configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial:\n\nI - no âmbito da unidade doméstica, compreendida como o espaço de convívio permanente de pessoas, com ou sem vínculo familiar, inclusive as esporadicamente agregadas;\n\nII - no âmbito da família, compreendida como a comunidade formada por indivíduos que são ou se consideram aparentados, unidos por laços naturais, por afinidade ou por vontade expressa;\n\nIII - em qualquer relação íntima de afeto, na qual o agressor conviva ou tenha convivido com a ofendida, independentemente de coabitação.\n\nParágrafo único. As relações pessoais enunciadas neste artigo independem de orientação sexual."},{"chave":"art-6","sequencia":6,"caminho":["LEI MARIA DA PENHA","TÍTULO II — DA VIOLÊNCIA DOMÉSTICA E FAMILIAR CONTRA A MULHER","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 6º","conteudo":"A violência doméstica e familiar contra a mulher constitui uma das formas de violação dos direitos humanos."},{"chave":"art-7","sequencia":7,"caminho":["LEI MARIA DA PENHA","TÍTULO II — DA VIOLÊNCIA DOMÉSTICA E FAMILIAR CONTRA A MULHER","CAPÍTULO II — DAS FORMAS DE VIOLÊNCIA DOMÉSTICA E FAMILIAR CONTRA A MULHER"],"titulo":"CAPÍTULO II — DAS FORMAS DE VIOLÊNCIA DOMÉSTICA E FAMILIAR CONTRA A MULHER","rotulo":"Art. 7º","conteudo":"São formas de violência doméstica e familiar contra a mulher, entre outras:\n\nI - a violência física, entendida como qualquer conduta que ofenda sua integridade ou saúde corporal;\n\nII - a violência psicológica, entendida como qualquer conduta que lhe cause dano emocional e diminuição da autoestima ou que lhe prejudique e perturbe o pleno desenvolvimento ou que vise degradar ou controlar suas ações, comportamentos, crenças e decisões, mediante ameaça, constrangimento, humilhação, manipulação, isolamento, vigilância constante, perseguição contumaz, insulto, chantagem, violação de sua intimidade, ridicularização, exploração e limitação do direito de ir e vir ou qualquer outro meio que lhe cause prejuízo à saúde psicológica e à autodeterminação; (Inciso com redação dada pela Lei nº 13.772, de 19/12/2018)\n\nIII - a violência sexual, entendida como qualquer conduta que a constranja a presenciar, a manter ou a participar de relação sexual não desejada, mediante intimidação, ameaça, coação ou uso da força; que a induza a comercializar ou a utilizar, de qualquer modo, a sua sexualidade, que a impeça de usar qualquer método contraceptivo ou que a force ao matrimônio, à gravidez, ao aborto ou à prostituição, mediante coação, chantagem, suborno ou manipulação; ou que limite ou anule o exercício de seus direitos sexuais e reprodutivos;\n\nIV - a violência patrimonial, entendida como qualquer conduta que configure retenção, subtração, destruição parcial ou total de seus objetos, instrumentos de trabalho, documentos pessoais, bens, valores e direitos ou recursos econômicos, incluindo os destinados a satisfazer suas necessidades;\n\nV - a violência moral, entendida como qualquer conduta que configure calúnia, difamação ou injúria.\n\nVI - a violência vicária, entendida como qualquer forma de violência praticada contra descendente, ascendente, dependente, enteado, parente, pessoa sob guarda ou responsabilidade direta da mulher ou pessoa de sua rede de apoio, com vistas a atingi-la. (Inciso acrescido pela Lei nº 15.384, de 9/4/2026)"},{"chave":"art-8","sequencia":8,"caminho":["LEI MARIA DA PENHA","TÍTULO III — DA ASSISTÊNCIA À MULHER EM SITUAÇÃO DE VIOLÊNCIA DOMÉSTICA E FAMILIAR","CAPÍTULO I — DAS MEDIDAS INTEGRADAS DE PREVENÇÃO"],"titulo":"CAPÍTULO I — DAS MEDIDAS INTEGRADAS DE PREVENÇÃO","rotulo":"Art. 8º","conteudo":"A política pública que visa coibir a violência doméstica e familiar contra a mulher far-se-á por meio de um conjunto articulado de ações da União, dos Estados, do Distrito Federal e dos Municípios e de ações não-governamentais, tendo por diretrizes:\n\nI - a integração operacional do Poder Judiciário, do Ministério Público e da Defensoria Pública com as áreas de segurança pública, assistência social, saúde, educação, trabalho e habitação;\n\nII - a promoção de estudos e pesquisas, estatísticas e outras informações relevantes, com a perspectiva de gênero e de raça ou etnia, concernentes às causas, às consequências e à frequência da violência doméstica e familiar contra a mulher, para a sistematização de dados, a serem unificados nacionalmente, e a avaliação periódica dos resultados das medidas adotadas;\n\nIII - o respeito, nos meios de comunicação social, dos valores éticos e sociais da pessoa e da família, de forma a coibir os papéis estereotipados que legitimem ou exacerbem a violência doméstica e familiar, de acordo com o estabelecido no inciso III do art. 1º, no inciso IV do art. 3º e no inciso IV do art. 221 da Constituição Federal;\n\nIV - a implementação de atendimento policial especializado para as mulheres, em particular nas Delegacias de Atendimento à Mulher;\n\nV - a promoção e a realização de campanhas educativas de prevenção da violência doméstica e familiar contra a mulher, voltadas ao público escolar e à sociedade em geral, e a difusão desta Lei e dos instrumentos de proteção aos direitos humanos das mulheres;\n\nVI - a celebração de convênios, protocolos, ajustes, termos ou outros instrumentos de promoção de parceria entre órgãos governamentais ou entre estes e entidades não-governamentais, tendo por objetivo a implementação de programas de erradicação da violência doméstica e familiar contra a mulher;\n\nVII - a capacitação permanente das Polícias Civil e Militar, da Guarda Municipal, do Corpo de Bombeiros e dos profissionais pertencentes aos órgãos e às áreas enunciados no inciso I quanto às questões de gênero e de raça ou etnia;\n\nVIII - a promoção de programas educacionais que disseminem valores éticos de irrestrito respeito à dignidade da pessoa humana com a perspectiva de gênero e de raça ou etnia;\n\nIX - o destaque, nos currículos escolares de todos os níveis de ensino, para os conteúdos relativos aos direitos humanos, à equidade de gênero e de raça ou etnia e ao problema da violência doméstica e familiar contra a mulher."},{"chave":"art-9","sequencia":9,"caminho":["LEI MARIA DA PENHA","TÍTULO III — DA ASSISTÊNCIA À MULHER EM SITUAÇÃO DE VIOLÊNCIA DOMÉSTICA E FAMILIAR","CAPÍTULO II — DA ASSISTÊNCIA À MULHER EM SITUAÇÃO DE VIOLÊNCIA DOMÉSTICA E FAMILIAR"],"titulo":"CAPÍTULO II — DA ASSISTÊNCIA À MULHER EM SITUAÇÃO DE VIOLÊNCIA DOMÉSTICA E FAMILIAR","rotulo":"Art. 9º","conteudo":"A assistência à mulher em situação de violência doméstica e familiar será prestada em caráter prioritário no Sistema Único de Saúde (SUS) e no Sistema Único de Segurança Pública (Susp), de forma articulada e conforme os princípios e as diretrizes previstos na Lei nº 8.742, de 7 de dezembro de 1993 (Lei Orgânica da Assistência Social), e em outras normas e políticas públicas de proteção, e emergencialmente, quando for o caso. (“Caput” do artigo com redação dada pela Lei nº 14.887, de 12/6/2024)\n\n§ 1º O juiz determinará, por prazo certo, a inclusão da mulher em situação de violência doméstica e familiar no cadastro de programas assistenciais do governo federal, estadual e municipal.\n\n§ 2º O juiz assegurará à mulher em situação de violência doméstica e familiar, para preservar sua integridade física e psicológica:\n\nI - acesso prioritário à remoção quando servidora pública, integrante da administração direta ou indireta;\n\nII - manutenção do vínculo trabalhista, quando necessário o afastamento do local de trabalho, por até seis meses;\n\nIII - encaminhamento à assistência judiciária, quando for o caso, inclusive para eventual ajuizamento da ação de separação judicial, de divórcio, de anulação de casamento ou de dissolução de união estável perante o juízo competente. (Inciso acrescido pela Lei nº 13.894, de 29/10/2019)\n\n§ 3º A assistência à mulher em situação de violência doméstica e familiar compreenderá o acesso aos benefícios decorrentes do desenvolvimento científico e tecnológico, incluindo os serviços de contracepção de emergência, a profilaxia das Doenças Sexualmente Transmissíveis (DST) e da Síndrome da Imunodeficiência Adquirida (AIDS) e outros procedimentos médicos necessários e cabíveis nos casos de violência sexual.\n\n§ 4º Aquele que, por ação ou omissão, causar lesão, violência física, sexual ou psicológica e dano moral ou patrimonial a mulher fica obrigado a ressarcir todos os danos causados, inclusive ressarcir ao Sistema Único de Saúde (SUS), de acordo com a tabela SUS, os custos relativos aos serviços de saúde prestados para o total tratamento das vítimas em situação de violência doméstica e familiar, recolhidos os recursos assim arrecadados ao Fundo de Saúde do ente federado responsável pelas unidades de saúde que prestarem os serviços. (Parágrafo acrescido pela Lei nº 13.871, de 17/9/2019, publicada no DOU de 18/9/2019, em vigor 45 dias após a publicação)\n\n§ 5º Os dispositivos de segurança destinados ao uso em caso de perigo iminente e disponibilizados para o monitoramento das vítimas de violência doméstica ou familiar amparadas por medidas protetivas terão seus custos ressarcidos pelo agressor. (Parágrafo acrescido pela Lei nº 13.871, de 17/9/2019, publicada no DOU de 18/9/2019, em vigor 45 dias após a publicação)\n\n§ 6º O ressarcimento de que tratam os §§ 4º e 5º deste artigo não poderá importar ônus de qualquer natureza ao patrimônio da mulher e dos seus dependentes, nem configurar atenuante ou ensejar possibilidade de substituição da pena aplicada. (Parágrafo acrescido pela Lei nº 13.871, de 17/9/2019, publicada no DOU de 18/9/2019, em vigor 45 dias após a publicação)\n\n§ 7º A mulher em situação de violência doméstica e familiar tem prioridade para matricular seus dependentes em instituição de educação básica mais próxima de seu domicílio, ou transferi-los para essa instituição, mediante a apresentação dos documentos comprobatórios do registro da ocorrência policial ou do processo de violência doméstica e familiar em curso. (Parágrafo acrescido pela Lei nº 13.882, de 8/10/2019)\n\n§ 8º Serão sigilosos os dados da ofendida e de seus dependentes matriculados ou transferidos conforme o disposto no § 7º deste artigo, e o acesso às informações será reservado ao juiz, ao Ministério Público e aos órgãos competentes do poder público. (Parágrafo acrescido pela Lei nº 13.882, de 8/10/2019 e republicado no DOU de 11/10/2019)"},{"chave":"art-10","sequencia":10,"caminho":["LEI MARIA DA PENHA","TÍTULO III — DA ASSISTÊNCIA À MULHER EM SITUAÇÃO DE VIOLÊNCIA DOMÉSTICA E FAMILIAR","CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL"],"titulo":"CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL","rotulo":"Art. 10.","conteudo":"Na hipótese da iminência ou da prática de violência doméstica e familiar contra a mulher, à autoridade policial que tomar conhecimento da ocorrência adotará, de imediato, as providências legais cabíveis.\n\nParágrafo único. Aplica-se o disposto no caput deste artigo ao descumprimento de medida protetiva de urgência deferida."},{"chave":"art-10-a","sequencia":11,"caminho":["LEI MARIA DA PENHA","TÍTULO III — DA ASSISTÊNCIA À MULHER EM SITUAÇÃO DE VIOLÊNCIA DOMÉSTICA E FAMILIAR","CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL"],"titulo":"CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL","rotulo":"Art. 10-A","conteudo":"É direito da mulher em situação de violência doméstica e familiar o atendimento policial e pericial especializado, ininterrupto e prestado por servidores - preferencialmente do sexo feminino - previamente capacitados.\n\n§ 1º A inquirição de mulher em situação de violência doméstica e familiar ou de testemunha de violência doméstica, quando se tratar de crime contra a mulher, obedecerá às seguintes diretrizes:\n\nI - salvaguarda da integridade física, psíquica e emocional da depoente, considerada a sua condição peculiar de pessoa em situação de violência doméstica e familiar;\n\nII - garantia de que, em nenhuma hipótese, a mulher em situação de violência doméstica e familiar, familiares e testemunhas terão contato direto com investigados ou suspeitos e pessoas a eles relacionadas;\n\nIII - não revitimização da depoente, evitando sucessivas inquirições sobre o mesmo fato nos âmbitos criminal, cível e administrativo, bem como questionamentos sobre a vida privada.\n\n§ 2º Na inquirição de mulher em situação de violência doméstica e familiar ou de testemunha de delitos de que trata esta Lei, adotar-se-á, preferencialmente, o seguinte procedimento:\n\nI - a inquirição será feita em recinto especialmente projetado para esse fim, o qual conterá os equipamentos próprios e adequados à idade da mulher em situação de violência doméstica e familiar ou testemunha e ao tipo e à gravidade da violência sofrida;\n\nII - quando for o caso, a inquirição será intermediada por profissional especializado em violência doméstica e familiar designado pela autoridade judiciária ou policial;\n\nIII - o depoimento será registrado em meio eletrônico ou magnético, devendo a degravação e a mídia integrar o inquérito. (Artigo acrescido pela Lei nº 13.505, de 8/11/2017)"},{"chave":"art-11","sequencia":12,"caminho":["LEI MARIA DA PENHA","TÍTULO III — DA ASSISTÊNCIA À MULHER EM SITUAÇÃO DE VIOLÊNCIA DOMÉSTICA E FAMILIAR","CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL"],"titulo":"CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL","rotulo":"Art. 11.","conteudo":"No atendimento à mulher em situação de violência doméstica e familiar, a autoridade policial deverá, entre outras providências:\n\nI - garantir proteção policial, quando necessário, comunicando de imediato ao Ministério Público e ao Poder Judiciário;\n\nII - encaminhar a ofendida ao hospital ou posto de saúde e ao Instituto Médico Legal;\n\nIII - fornecer transporte para a ofendida e seus dependentes para abrigo ou local seguro, quando houver risco de vida;\n\nIV - se necessário, acompanhar a ofendida para assegurar a retirada de seus pertences do local da ocorrência ou do domicílio familiar;\n\nV - informar à ofendida os direitos a ela conferidos nesta Lei e os serviços disponíveis, inclusive os de assistência judiciária para o eventual ajuizamento perante o juízo competente da ação de separação judicial, de divórcio, de anulação de casamento ou de dissolução de união estável. (Inciso com redação dada pela Lei nº 13.894, de 29/10/2019)\n\nParágrafo único. Verificados indícios de redução a condição análoga à de escravo ou outra forma de violência doméstica contra a trabalhadora doméstica, a autoridade policial que tomar conhecimento da ocorrência deverá comunicá-la, em até 48 (quarenta e oito) horas, à unidade regional do Ministério do Trabalho e Emprego e ao Ministério Público do Trabalho. (Parágrafo único acrescido pela Lei nº 15.455, de 1º/7/2026)"},{"chave":"art-12","sequencia":13,"caminho":["LEI MARIA DA PENHA","TÍTULO III — DA ASSISTÊNCIA À MULHER EM SITUAÇÃO DE VIOLÊNCIA DOMÉSTICA E FAMILIAR","CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL"],"titulo":"CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL","rotulo":"Art. 12.","conteudo":"Em todos os casos de violência doméstica e familiar contra a mulher, feito o registro da ocorrência, deverá a autoridade policial adotar, de imediato, os seguintes procedimentos, sem prejuízo daqueles previstos no Código de Processo Penal:\n\nI - ouvir a ofendida, lavrar o boletim de ocorrência e tomar a representação a termo, se apresentada; (Vide ADIN nº 4.424/2010, publicada no DOU de 17/2/2012)\n\nII - colher todas as provas que servirem para o esclarecimento do fato e de suas circunstâncias;\n\nIII - remeter, no prazo de 48 (quarenta e oito) horas, expediente apartado ao juiz com o pedido da ofendida, para a concessão de medidas protetivas de urgência;\n\nIV - determinar que se proceda ao exame de corpo de delito da ofendida e requisitar outros exames periciais necessários;\n\nV - ouvir o agressor e as testemunhas;\n\nVI - ordenar a identificação do agressor e fazer juntar aos autos sua folha de antecedentes criminais, indicando a existência de mandado de prisão ou registro de outras ocorrências policiais contra ele;\n\nVI-A - verificar se o agressor possui registro de porte ou posse de arma de fogo e, na hipótese de existência, juntar aos autos essa informação, bem como notificar a ocorrência à instituição responsável pela concessão do registro ou da emissão do porte, nos termos da Lei nº 10.826, de 22 de dezembro de 2003 (Estatuto do Desarmamento); (Inciso acrescido pela Lei nº 13.880, de 8/10/2019)\n\nVII - remeter, no prazo legal, os autos do inquérito policial ao juiz e ao Ministério Público.\n\n§ 1º O pedido da ofendida será tomado a termo pela autoridade policial e deverá conter:\n\nI - qualificação da ofendida e do agressor;\n\nII - nome e idade dos dependentes;\n\nIII - descrição sucinta do fato e das medidas protetivas solicitadas pela ofendida;\n\nIV - informação sobre a condição de a ofendida ser pessoa com deficiência e se da violência sofrida resultou deficiência ou agravamento de deficiência preexistente. (Inciso acrescido pela Lei nº 13.836, de 4/6/2019)\n\n§ 2º A autoridade policial deverá anexar ao documento referido no § 1º o boletim de ocorrência e cópia de todos os documentos disponíveis em posse da ofendida.\n\n§ 3º Serão admitidos como meios de prova os laudos ou prontuários médicos fornecidos por hospitais e postos de saúde."},{"chave":"art-12-a","sequencia":14,"caminho":["LEI MARIA DA PENHA","TÍTULO III — DA ASSISTÊNCIA À MULHER EM SITUAÇÃO DE VIOLÊNCIA DOMÉSTICA E FAMILIAR","CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL"],"titulo":"CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL","rotulo":"Art. 12-A","conteudo":"Os Estados e o Distrito Federal, na formulação de suas políticas e planos de atendimento à mulher em situação de violência doméstica e familiar, darão prioridade, no âmbito da Polícia Civil, à criação de Delegacias Especializadas de Atendimento à Mulher (Deams), de Núcleos Investigativos de Feminicídio e de equipes especializadas para o atendimento e a investigação das violências graves contra a mulher. (Artigo acrescido pela Lei nº 13.505, de 8/11/2017)"},{"chave":"art-12-b","sequencia":15,"caminho":["LEI MARIA DA PENHA","TÍTULO III — DA ASSISTÊNCIA À MULHER EM SITUAÇÃO DE VIOLÊNCIA DOMÉSTICA E FAMILIAR","CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL"],"titulo":"CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL","rotulo":"Art. 12-B","conteudo":"(VETADO na Lei nº 13.505, de 8/11/2017)\n\n§ 1º (VETADO na Lei nº 13.505, de 8/11/2017)\n\n§ 2º (VETADO na Lei nº 13.505, de 8/11/2017)\n\n§ 3º A autoridade policial poderá requisitar os serviços públicos necessários à defesa da mulher em situação de violência doméstica e familiar e de seus dependentes. (Parágrafo acrescido pela Lei nº 13.505, de 8/11/2017)"},{"chave":"art-12-c","sequencia":16,"caminho":["LEI MARIA DA PENHA","TÍTULO III — DA ASSISTÊNCIA À MULHER EM SITUAÇÃO DE VIOLÊNCIA DOMÉSTICA E FAMILIAR","CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL"],"titulo":"CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL","rotulo":"Art. 12-C","conteudo":"Verificada a existência de risco atual ou iminente à vida ou à integridade física, sexual, psicológica, moral ou patrimonial da mulher em situação de violência doméstica e familiar, ou de seus dependentes, o agressor será imediatamente afastado do lar, domicílio ou local de convivência com a ofendida: (“Caput” do artigo acrescido pela Lei nº 13.827, de 13/5/2019, e com redação dada pela Lei nº 15.411, de 20/5/2026)\n\nI - pela autoridade judicial; (Inciso acrescido pela Lei nº 13.827, de 13/5/2019)\n\nII - pelo delegado de polícia, quando o Município não for sede de comarca; ou (Inciso acrescido pela Lei nº 13.827, de 13/5/2019)\n\nIII - pelo policial, quando o Município não for sede de comarca e não houver delegado disponível no momento da denúncia. (Inciso acrescido pela Lei nº 13.827, de 13/5/2019)\n\n§ 1º Nas hipóteses dos incisos II e III do caput deste artigo, o juiz será comunicado no prazo máximo de 24 (vinte e quatro) horas e decidirá, em igual prazo, sobre a manutenção ou a revogação da medida aplicada, devendo dar ciência ao Ministério Público concomitantemente. (Parágrafo acrescido pela Lei nº 13.827, de 13/5/2019)\n\n§ 2º Nos casos de risco à integridade física da ofendida ou à efetividade da medida protetiva de urgência, não será concedida liberdade provisória ao preso. (Parágrafo acrescido pela Lei nº 13.827, de 13/5/2019)"},{"chave":"art-12-d","sequencia":17,"caminho":["LEI MARIA DA PENHA","TÍTULO III — DA ASSISTÊNCIA À MULHER EM SITUAÇÃO DE VIOLÊNCIA DOMÉSTICA E FAMILIAR","CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL"],"titulo":"CAPÍTULO III — DO ATENDIMENTO PELA AUTORIDADE POLICIAL","rotulo":"Art. 12-D","conteudo":"Verificada a existência de risco atual ou iminente à vida ou à integridade física ou psicológica da mulher em situação de violência doméstica e familiar, ou de seus dependentes, o agressor será imediatamente submetido à monitoração eletrônica:\n\nI - pela autoridade judicial;\n\nII - pelo delegado de polícia, quando o Município não for sede de comarca.\n\nParágrafo único. Na hipótese do inciso II do caput deste artigo, o juiz será comunicado no prazo máximo de 24 (vinte e quatro) horas e decidirá, em igual prazo, sobre a manutenção ou a revogação da medida aplicada, devendo dar ciência ao Ministério Público concomitantemente. (Artigo acrescido pela Lei nº 15.383, de 9/4/2026)"},{"chave":"art-13","sequencia":18,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 13.","conteudo":"Ao processo, ao julgamento e à execução das causas cíveis e criminais decorrentes da prática de violência doméstica e familiar contra a mulher aplicar-se-ão as normas dos Códigos de Processo Penal e Processo Civil e da legislação específica relativa à criança, ao adolescente e ao idoso que não conflitarem com o estabelecido nesta Lei."},{"chave":"art-14","sequencia":19,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 14.","conteudo":"Os Juizados de Violência Doméstica e Familiar contra a Mulher, órgãos da Justiça Ordinária com competência cível e criminal, poderão ser criados pela União, no Distrito Federal e nos Territórios, e pelos Estados, para o processo, o julgamento e a execução das causas decorrentes da prática de violência doméstica e familiar contra a mulher.\n\nParágrafo único. Os atos processuais poderão realizar-se em horário noturno, conforme dispuserem as normas de organização judiciária."},{"chave":"art-14-a","sequencia":20,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 14-A","conteudo":"A ofendida tem a opção de propor ação de divórcio ou de dissolução de união estável no Juizado de Violência Doméstica e Familiar contra a Mulher.\n\n§ 1º Exclui-se da competência dos Juizados de Violência Doméstica e Familiar contra a Mulher a pretensão relacionada à partilha de bens.\n\n§ 2º Iniciada a situação de violência doméstica e familiar após o ajuizamento da ação de divórcio ou de dissolução de união estável, a ação terá preferência no juízo onde estiver. (Artigo acrescido pela Lei nº 13.894, de 29/10/2019, vetado pelo Presidente da República, mantido pelo Congresso Nacional e publicado no DOU de 11/12/2019)"},{"chave":"art-15","sequencia":21,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 15.","conteudo":"É competente, por opção da ofendida, para os processos cíveis regidos por esta Lei, o Juizado:\n\nI - do seu domicílio ou de sua residência;\n\nII - do lugar do fato em que se baseou a demanda;\n\nIII - do domicílio do agressor."},{"chave":"art-16","sequencia":22,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 16.","conteudo":"Nas ações penais públicas condicionadas à representação da ofendida de que trata esta Lei, só será admitida a renúncia à representação perante o juiz, em audiência especialmente designada com tal finalidade, antes do recebimento da denúncia e ouvido o Ministério Público. (Vide ADIN nº 4.424/2010, publicada no DOU de 17/2/2012) (Vide ADI nº 7.267/2022, publicada no DOU de 4/9/2023)\n\nParágrafo único. A audiência prevista no caput deste artigo tem por objetivo confirmar a retratação da vítima, não a representação, e somente será designada pelo juiz mediante manifestação expressa de seu desejo de se retratar, apresentada por escrito ou oralmente antes do recebimento da denúncia, devendo a retratação ser devidamente registrada nos autos. (Parágrafo único acrescido pela Lei nº 15.380, de 6/4/2026)"},{"chave":"art-16-a","sequencia":23,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 16-A","conteudo":"Nos crimes praticados no âmbito de violência doméstica e familiar contra a mulher, a ofendida decai do direito de queixa ou de representação se não o exerce no prazo de 12 (doze) meses, contado do dia em que veio a saber quem é o autor do crime, ou, no caso do § 3º do art. 100 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), do dia em que se esgota o prazo para oferecimento da denúncia. (Artigo acrescido pela Lei nº 15.438, de 18/6/2026)"},{"chave":"art-17","sequencia":24,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 17.","conteudo":"É vedada a aplicação, nos casos de violência doméstica e familiar contra a mulher, de penas de cesta básica ou outras de prestação pecuniária, bem como a substituição de pena que implique o pagamento isolado de multa."},{"chave":"art-17-a","sequencia":25,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 17-A","conteudo":"O nome da ofendida ficará sob sigilo nos processos em que se apuram crimes praticados no contexto de violência doméstica e familiar contra a mulher.\n\nParágrafo único. O sigilo referido no caput deste artigo não abrange o nome do autor do fato, tampouco os demais dados do processo. (Artigo acrescido pela Lei nº 14.857, de 21/5/2024, publicada no DOU de 22/5/2024, em vigor 180 dias após a publicação)"},{"chave":"art-18","sequencia":26,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO II — DAS MEDIDAS PROTETIVAS DE URGÊNCIA","SEÇÃO I — DISPOSIÇÕES GERAIS"],"titulo":"SEÇÃO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 18.","conteudo":"Recebido o expediente com o pedido da ofendida, caberá ao juiz, no prazo de 48 (quarenta e oito) horas:\n\nI - conhecer do expediente e do pedido e decidir sobre as medidas protetivas de urgência;\n\nII - determinar o encaminhamento da ofendida ao órgão de assistência judiciária, quando for o caso, inclusive para o ajuizamento da ação de separação judicial, de divórcio, de anulação de casamento ou de dissolução de união estável perante o juízo competente; (Inciso com redação dada pela Lei nº 13.894, de 29/10/2019)\n\nIII - comunicar ao Ministério Público para que adote as providências cabíveis;\n\nIV - determinar a apreensão imediata de arma de fogo sob a posse do agressor. (Inciso acrescido pela Lei nº 13.880, de 8/10/2019)"},{"chave":"art-19","sequencia":27,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO II — DAS MEDIDAS PROTETIVAS DE URGÊNCIA","SEÇÃO I — DISPOSIÇÕES GERAIS"],"titulo":"SEÇÃO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 19.","conteudo":"As medidas protetivas de urgência poderão ser concedidas pelo juiz, a requerimento do Ministério Público ou a pedido da ofendida.\n\n§ 1º As medidas protetivas de urgência poderão ser concedidas de imediato, independentemente de audiência das partes e de manifestação do Ministério Público, devendo este ser prontamente comunicado.\n\n§ 2º As medidas protetivas de urgência serão aplicadas isolada ou cumulativamente, e poderão ser substituídas a qualquer tempo por outras de maior eficácia, sempre que os direitos reconhecidos nesta Lei forem ameaçados ou violados.\n\n§ 3º Poderá o juiz, a requerimento do Ministério Público ou a pedido da ofendida, conceder novas medidas protetivas de urgência ou rever aquelas já concedidas, se entender necessário à proteção da ofendida, de seus familiares e de seu patrimônio, ouvido o Ministério Público.\n\n§ 4º As medidas protetivas de urgência serão concedidas em juízo de cognição sumária a partir do depoimento da ofendida perante a autoridade policial ou da apresentação de suas alegações escritas e poderão ser indeferidas no caso de avaliação pela autoridade de inexistência de risco à integridade física, psicológica, sexual, patrimonial ou moral da ofendida ou de seus dependentes. (Parágrafo acrescido pela Lei nº 14.550, de 19/4/2023)\n\n§ 5º As medidas protetivas de urgência serão concedidas independentemente da tipificação penal da violência, do ajuizamento de ação penal ou cível, da existência de inquérito policial ou do registro de boletim de ocorrência. (Parágrafo acrescido pela Lei nº 14.550, de 19/4/2023)\n\n§ 6º As medidas protetivas de urgência vigorarão enquanto persistir risco à integridade física, psicológica, sexual, patrimonial ou moral da ofendida ou de seus dependentes. (Parágrafo acrescido pela Lei nº 14.550, de 19/4/2023)"},{"chave":"art-20","sequencia":28,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO II — DAS MEDIDAS PROTETIVAS DE URGÊNCIA","SEÇÃO I — DISPOSIÇÕES GERAIS"],"titulo":"SEÇÃO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 20.","conteudo":"Em qualquer fase do inquérito policial ou da instrução criminal, caberá a prisão preventiva do agressor, decretada pelo juiz, de ofício, a requerimento do Ministério Público ou mediante representação da autoridade policial.\n\nParágrafo único. O juiz poderá revogar a prisão preventiva se, no curso do processo, verificar a falta de motivo para que subsista, bem como de novo decretá-la, se sobrevierem razões que a justifiquem."},{"chave":"art-21","sequencia":29,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO II — DAS MEDIDAS PROTETIVAS DE URGÊNCIA","SEÇÃO I — DISPOSIÇÕES GERAIS"],"titulo":"SEÇÃO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 21.","conteudo":"A ofendida deverá ser notificada dos atos processuais relativos ao agressor, especialmente dos pertinentes ao ingresso e à saída da prisão, sem prejuízo da intimação do advogado constituído ou do defensor público.\n\nParágrafo único. A ofendida não poderá entregar intimação ou notificação ao agressor."},{"chave":"art-22","sequencia":30,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO II — DAS MEDIDAS PROTETIVAS DE URGÊNCIA","SEÇÃO II — DAS MEDIDAS PROTETIVAS DE URGÊNCIA QUE OBRIGAM O AGRESSOR"],"titulo":"SEÇÃO II — DAS MEDIDAS PROTETIVAS DE URGÊNCIA QUE OBRIGAM O AGRESSOR","rotulo":"Art. 22.","conteudo":"Constatada a prática de violência doméstica e familiar contra a mulher, nos termos desta Lei, o juiz poderá aplicar, de imediato, ao agressor, em conjunto ou separadamente, as seguintes medidas protetivas de urgência, entre outras:\n\nI - suspensão da posse ou restrição do porte de armas, com comunicação ao órgão competente, nos termos da Lei nº 10.826, de 22 de dezembro de 2003;\n\nII - afastamento do lar, domicílio ou local de convivência com a ofendida;\n\nIII - proibição de determinadas condutas, entre as quais:\n\na) aproximação da ofendida, de seus familiares e das testemunhas, fixando o limite mínimo de distância entre estes e o agressor;\n\nb) contato com a ofendida, seus familiares e testemunhas por qualquer meio de comunicação;\n\nc) frequentação de determinados lugares a fim de preservar a integridade física e psicológica da ofendida;\n\nIV - restrição ou suspensão de visitas aos dependentes menores, ouvida a equipe de atendimento multidisciplinar ou serviço similar;\n\nV - prestação de alimentos provisionais ou provisórios;\n\nVI - comparecimento do agressor a programas de recuperação e reeducação; e (Inciso acrescido pela Lei nº 13.984, de 3/4/2020)\n\nVII - acompanhamento psicossocial do agressor, por meio de atendimento individual e/ou em grupo de apoio. (Inciso acrescido pela Lei nº 13.984, de 3/4/2020)\n\nVIII - monitoração eletrônica, disponibilizando-se à vítima aplicação ou dispositivo de segurança que alerte sobre eventual aproximação do agressor. (Inciso acrescido pela Lei nº 15.383, de 9/4/2026)\n\n§ 1º As medidas referidas neste artigo não impedem a aplicação de outras previstas na legislação em vigor, sempre que a segurança da ofendida ou as circunstâncias o exigirem, devendo a providência ser comunicada ao Ministério Público.\n\n§ 2º Na hipótese de aplicação do inciso I, encontrando-se o agressor nas condições mencionadas no caput e incisos do art. 6º da Lei nº 10.826, de 22 de dezembro de 2003, o juiz comunicará ao respectivo órgão, corporação ou instituição as medidas protetivas de urgência concedidas e determinará a restrição do porte de armas, ficando o superior imediato do agressor responsável pelo cumprimento da determinação judicial, sob pena de incorrer nos crimes de prevaricação ou de desobediência, conforme o caso.\n\n§ 3º Para garantir a efetividade das medidas protetivas de urgência, poderá o juiz requisitar, a qualquer momento, auxílio da força policial.\n\n§ 4º Na aplicação das medidas protetivas de urgência, o juiz concederá a tutela específica ou determinará providências que assegurem a obtenção de tutela pelo resultado prático equivalente. (Parágrafo com redação dada pela Lei nº 15.412, de 20/5/2026)\n\n§ 5º (Parágrafo acrescido pela Lei nº 15.125, de 24/4/2025 , e revogado pela Lei nº 15.383, de 9/4/2026)\n\n§ 6º A aplicação da medida prevista no inciso VIII do caput deste artigo terá prioridade nos casos em que houver descumprimento de medidas protetivas anteriormente impostas ou quando for verificado risco iminente à integridade física ou psicológica da vítima. (Parágrafo acrescido pela Lei nº 15.383, de 9/4/2026)\n\n§ 7º Para a efetivação da medida prevista no inciso VIII do caput deste artigo, a autoridade competente promoverá a instalação do equipamento e instruirá o agressor sobre o seu funcionamento e as áreas de exclusão onde não poderá circular, conforme definido na decisão da autoridade judicial, devendo a ciência constar de termo nos autos. (Parágrafo acrescido pela Lei nº 15.383, de 9/4/2026)\n\n§ 8º O sistema de monitoração eletrônica de que trata o inciso VIII do caput deste artigo deverá emitir alerta automático e simultâneo à vítima e à unidade policial mais próxima sempre que o agressor romper o perímetro de exclusão fixado judicialmente. (Parágrafo acrescido pela Lei nº 15.383, de 9/4/2026)\n\n§ 9º Nos casos previstos no § 6º deste artigo, a decisão judicial que deixar de aplicar a medida protetiva de monitoração eletrônica deverá apresentar fundamentação expressa quanto às razões da não aplicação da medida. (Parágrafo acrescido pela Lei nº 15.383, de 9/4/2026)\n\n§ 10 As medidas protetivas de natureza cível, inclusive as de prestação de alimentos provisionais ou provisórios, constituem título executivo judicial de pleno direito, dispensando a propositura de ação principal. (Parágrafo acrescido pela Lei nº 15.412, de 20/5/2026)"},{"chave":"art-23","sequencia":31,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO II — DAS MEDIDAS PROTETIVAS DE URGÊNCIA","SEÇÃO III — DAS MEDIDAS PROTETIVAS DE URGÊNCIA À OFENDIDA"],"titulo":"SEÇÃO III — DAS MEDIDAS PROTETIVAS DE URGÊNCIA À OFENDIDA","rotulo":"Art. 23.","conteudo":"Poderá o juiz, quando necessário, sem prejuízo de outras medidas:\n\nI - encaminhar a ofendida e seus dependentes a programa oficial ou comunitário de proteção ou de atendimento;\n\nII - determinar a recondução da ofendida e a de seus dependentes ao respectivo domicílio, após afastamento do agressor;\n\nIII - determinar o afastamento da ofendida do lar, sem prejuízo dos direitos relativos a bens, guarda dos filhos e alimentos;\n\nIV - determinar a separação de corpos;\n\nV - determinar a matrícula dos dependentes da ofendida em instituição de educação básica mais próxima do seu domicílio, ou a transferência deles para essa instituição, independentemente da existência de vaga; (Inciso acrescido pela Lei nº 13.882, de 8/10/2019)\n\nVI - conceder à ofendida auxílio-aluguel, com valor fixado em função de sua situação de vulnerabilidade social e econômica, por período não superior a 6 (seis) meses. (Inciso acrescido pela Lei nº 14.674, de 14/9/2023)"},{"chave":"art-24","sequencia":32,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO II — DAS MEDIDAS PROTETIVAS DE URGÊNCIA","SEÇÃO III — DAS MEDIDAS PROTETIVAS DE URGÊNCIA À OFENDIDA"],"titulo":"SEÇÃO III — DAS MEDIDAS PROTETIVAS DE URGÊNCIA À OFENDIDA","rotulo":"Art. 24.","conteudo":"Para a proteção patrimonial dos bens da sociedade conjugal ou daqueles de propriedade particular da mulher, o juiz poderá determinar, liminarmente, as seguintes medidas, entre outras:\n\nI - restituição de bens indevidamente subtraídos pelo agressor à ofendida;\n\nII - proibição temporária para a celebração de atos e contratos de compra, venda e locação de propriedade em comum, salvo expressa autorização judicial;\n\nIII - suspensão das procurações conferidas pela ofendida ao agressor;\n\nIV - prestação de caução provisória, mediante depósito judicial, por perdas e danos materiais decorrentes da prática de violência doméstica e familiar contra a ofendida.\n\nParágrafo único. Deverá o juiz oficiar ao cartório competente para os fins previstos nos incisos II e III deste artigo."},{"chave":"art-24-a","sequencia":33,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO II — DAS MEDIDAS PROTETIVAS DE URGÊNCIA","SEÇÃO IV — DO CRIME DE DESCUMPRIMENTO DE MEDIDAS PROTETIVAS DE URGÊNCIA"],"titulo":"Descumprimento de Medidas Protetivas de Urgência","rotulo":"Art. 24-A","conteudo":"Descumprir decisão judicial que defere medidas protetivas de urgência previstas nesta Lei: (“Caput” do artigo acrescido pela Lei nº 13.641, de 3/4/2018)\n\nPena - reclusão, de 2 (dois) a 5 (cinco) anos, e multa. (Pena acrescida pela Lei nº 13.641, de 3/4/2018 , e com redação dada pela Lei nº 14.994, de 9/10/2024)\n\n§ 1º A configuração do crime independe da competência civil ou criminal do juiz que deferiu as medidas. (Parágrafo acrescido pela Lei nº 13.641, de 3/4/2018)\n\n§ 2º Na hipótese de prisão em flagrante, apenas a autoridade judicial poderá conceder fiança. (Parágrafo acrescido pela Lei nº 13.641, de 3/4/2018)\n\n§ 3º O disposto neste artigo não exclui a aplicação de outras sanções cabíveis. (Parágrafo acrescido pela Lei nº 13.641, de 3/4/2018)\n\n§ 4º A pena será aumentada de 1/3 (um terço) até a metade se o descumprimento decorrer da violação das áreas de exclusão monitoradas eletronicamente ou da remoção, violação ou alteração do dispositivo de monitoração sem autorização judicial. (Parágrafo acrescido pela Lei nº 15.383, de 9/4/2026)"},{"chave":"art-25","sequencia":34,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO III — DA ATUAÇÃO DO MINISTÉRIO PÚBLICO"],"titulo":"CAPÍTULO III — DA ATUAÇÃO DO MINISTÉRIO PÚBLICO","rotulo":"Art. 25.","conteudo":"O Ministério Público intervirá, quando não for parte, nas causas cíveis e criminais decorrentes da violência doméstica e familiar contra a mulher."},{"chave":"art-26","sequencia":35,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO III — DA ATUAÇÃO DO MINISTÉRIO PÚBLICO"],"titulo":"CAPÍTULO III — DA ATUAÇÃO DO MINISTÉRIO PÚBLICO","rotulo":"Art. 26.","conteudo":"Caberá ao Ministério Público, sem prejuízo de outras atribuições, nos casos de violência doméstica e familiar contra a mulher, quando necessário:\n\nI - requisitar força policial e serviços públicos de saúde, de educação, de assistência social e de segurança, entre outros;\n\nII - fiscalizar os estabelecimentos públicos e particulares de atendimento à mulher em situação de violência doméstica e familiar, e adotar, de imediato, as medidas administrativas ou judiciais cabíveis no tocante a quaisquer irregularidades constatadas;\n\nIII - cadastrar os casos de violência doméstica e familiar contra a mulher."},{"chave":"art-27","sequencia":36,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO IV — DA ASSISTÊNCIA JUDICIÁRIA"],"titulo":"CAPÍTULO IV — DA ASSISTÊNCIA JUDICIÁRIA","rotulo":"Art. 27.","conteudo":"Em todos os atos processuais, cíveis e criminais, a mulher em situação de violência doméstica e familiar deverá estar acompanhada de advogado, ressalvado o previsto no art. 19 desta Lei."},{"chave":"art-28","sequencia":37,"caminho":["LEI MARIA DA PENHA","TÍTULO IV — DOS PROCEDIMENTOS","CAPÍTULO IV — DA ASSISTÊNCIA JUDICIÁRIA"],"titulo":"CAPÍTULO IV — DA ASSISTÊNCIA JUDICIÁRIA","rotulo":"Art. 28.","conteudo":"É garantido a toda mulher em situação de violência doméstica e familiar o acesso aos serviços de Defensoria Pública ou de Assistência Judiciária Gratuita, nos termos da lei, em sede policial e judicial, mediante atendimento específico e humanizado."},{"chave":"art-29","sequencia":38,"caminho":["LEI MARIA DA PENHA","TÍTULO V — DA EQUIPE DE ATENDIMENTO MULTIDISCIPLINAR"],"titulo":"TÍTULO V — DA EQUIPE DE ATENDIMENTO MULTIDISCIPLINAR","rotulo":"Art. 29.","conteudo":"Os Juizados de Violência Doméstica e Familiar contra a Mulher que vierem a ser criados poderão contar com uma equipe de atendimento multidisciplinar, a ser integrada por profissionais especializados nas áreas psicossocial, jurídica e de saúde."},{"chave":"art-30","sequencia":39,"caminho":["LEI MARIA DA PENHA","TÍTULO V — DA EQUIPE DE ATENDIMENTO MULTIDISCIPLINAR"],"titulo":"TÍTULO V — DA EQUIPE DE ATENDIMENTO MULTIDISCIPLINAR","rotulo":"Art. 30.","conteudo":"Compete à equipe de atendimento multidisciplinar, entre outras atribuições que lhe forem reservadas pela legislação local, fornecer subsídios por escrito ao juiz, ao Ministério Público e à Defensoria Pública, mediante laudos ou verbalmente em audiência, e desenvolver trabalhos de orientação, encaminhamento, prevenção e outras medidas, voltados para a ofendida, o agressor e os familiares, com especial atenção às crianças e aos adolescentes."},{"chave":"art-31","sequencia":40,"caminho":["LEI MARIA DA PENHA","TÍTULO V — DA EQUIPE DE ATENDIMENTO MULTIDISCIPLINAR"],"titulo":"TÍTULO V — DA EQUIPE DE ATENDIMENTO MULTIDISCIPLINAR","rotulo":"Art. 31.","conteudo":"Quando a complexidade do caso exigir avaliação mais aprofundada, o juiz poderá determinar a manifestação de profissional especializado, mediante a indicação da equipe de atendimento multidisciplinar."},{"chave":"art-32","sequencia":41,"caminho":["LEI MARIA DA PENHA","TÍTULO V — DA EQUIPE DE ATENDIMENTO MULTIDISCIPLINAR"],"titulo":"TÍTULO V — DA EQUIPE DE ATENDIMENTO MULTIDISCIPLINAR","rotulo":"Art. 32.","conteudo":"O Poder Judiciário, na elaboração de sua proposta orçamentária, poderá prever recursos para a criação e manutenção da equipe de atendimento multidisciplinar, nos termos da Lei de Diretrizes Orçamentárias."},{"chave":"art-33","sequencia":42,"caminho":["LEI MARIA DA PENHA","TÍTULO VI — DISPOSIÇÕES TRANSITÓRIAS"],"titulo":"TÍTULO VI — DISPOSIÇÕES TRANSITÓRIAS","rotulo":"Art. 33.","conteudo":"Enquanto não estruturados os Juizados de Violência Doméstica e Familiar contra a Mulher, as varas criminais acumularão as competências cível e criminal para conhecer e julgar as causas decorrentes da prática de violência doméstica e familiar contra a mulher, observadas as previsões do Título IV desta Lei, subsidiada pela legislação processual pertinente.\n\nParágrafo único. Será garantido o direito de preferência, nas varas criminais, para o processo e o julgamento das causas referidas no caput ."},{"chave":"art-34","sequencia":43,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":"TÍTULO VII — DISPOSIÇÕES FINAIS","rotulo":"Art. 34.","conteudo":"A instituição dos Juizados de Violência Doméstica e Familiar contra a Mulher poderá ser acompanhada pela implantação das curadorias necessárias e do serviço de assistência judiciária."},{"chave":"art-35","sequencia":44,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":"TÍTULO VII — DISPOSIÇÕES FINAIS","rotulo":"Art. 35.","conteudo":"A União, o Distrito Federal, os Estados e os Municípios poderão criar e promover, no limite das respectivas competências:\n\nI - centros de atendimento integral e multidisciplinar para mulheres e respectivos dependentes em situação de violência doméstica e familiar;\n\nII - casas-abrigos para mulheres e respectivos dependentes menores em situação de violência doméstica e familiar;\n\nIII - delegacias, núcleos de defensoria pública, serviços de saúde e centros de perícia médico-legal especializados no atendimento à mulher em situação de violência doméstica e familiar;\n\nIV - programas e campanhas de enfrentamento da violência doméstica e familiar;\n\nV - centros de educação e de reabilitação para os agressores.\n\nParágrafo único. As campanhas a que se refere o inciso IV do caput deste artigo deverão contemplar informações sobre procedimentos e abordagens policiais, prevenção à revitimização, funcionamento das medidas protetivas de urgência e mecanismos de monitoração eletrônica. (Parágrafo único acrescido pela Lei nº 15.383, de 9/4/2026)"},{"chave":"art-36","sequencia":45,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":"TÍTULO VII — DISPOSIÇÕES FINAIS","rotulo":"Art. 36.","conteudo":"A União, os Estados, o Distrito Federal e os Municípios promoverão a adaptação de seus órgãos e de seus programas às diretrizes e aos princípios desta Lei."},{"chave":"art-37","sequencia":46,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":"TÍTULO VII — DISPOSIÇÕES FINAIS","rotulo":"Art. 37.","conteudo":"A defesa dos interesses e direitos transindividuais previstos nesta Lei poderá ser exercida, concorrentemente, pelo Ministério Público e por associação de atuação na área, regularmente constituída há pelo menos um ano, nos termos da legislação civil.\n\nParágrafo único. O requisito da pré-constituição poderá ser dispensado pelo juiz quando entender que não há outra entidade com representatividade adequada para o ajuizamento da demanda coletiva."},{"chave":"art-38","sequencia":47,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":"TÍTULO VII — DISPOSIÇÕES FINAIS","rotulo":"Art. 38.","conteudo":"As estatísticas sobre a violência doméstica e familiar contra a mulher serão incluídas nas bases de dados dos órgãos oficiais do Sistema de Justiça e Segurança a fim de subsidiar o sistema nacional de dados e informações relativo às mulheres.\n\nParágrafo único. As Secretarias de Segurança Pública dos Estados e do Distrito Federal poderão remeter suas informações criminais para a base de dados do Ministério da Justiça."},{"chave":"art-38-a","sequencia":48,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":"TÍTULO VII — DISPOSIÇÕES FINAIS","rotulo":"Art. 38-A","conteudo":"O juiz competente providenciará o registro da medida protetiva de urgência. (“Caput” do artigo acrescido pela Lei nº 13.827, de 13/5/2019)\n\nParágrafo único. As medidas protetivas de urgência serão, após sua concessão, imediatamente registradas em banco de dados mantido e regulamentado pelo Conselho Nacional de Justiça, garantido o acesso instantâneo do Ministério Público, da Defensoria Pública e dos órgãos de segurança pública e de assistência social, com vistas à fiscalização e à efetividade das medidas protetivas. (Parágrafo único acrescido pela Lei nº 13.827, de 13/5/2019 , com redação dada pela Lei nº 14.310, de 8/3/2022, publicada no DOU de 9/3/2022, em vigor 90 dias após a publicação)"},{"chave":"art-39","sequencia":49,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":"TÍTULO VII — DISPOSIÇÕES FINAIS","rotulo":"Art. 39.","conteudo":"A União, os Estados, o Distrito Federal e os Municípios, no limite de suas competências e nos termos das respectivas leis de diretrizes orçamentárias, poderão estabelecer dotações orçamentárias específicas, em cada exercício financeiro, para a implementação das medidas estabelecidas nesta Lei.\n\nParágrafo único. Na implementação das medidas estabelecidas nesta Lei, os entes federativos deverão observar, entre as prioridades de alocação de recursos, a aquisição e a manutenção de equipamentos de monitoração eletrônica para agressores e de dispositivos de segurança para as vítimas. (Parágrafo único acrescido pela Lei nº 15.383, de 9/4/2026)"},{"chave":"art-40","sequencia":50,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":"TÍTULO VII — DISPOSIÇÕES FINAIS","rotulo":"Art. 40.","conteudo":"As obrigações previstas nesta Lei não excluem outras decorrentes dos princípios por ela adotados."},{"chave":"art-40-a","sequencia":51,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":"TÍTULO VII — DISPOSIÇÕES FINAIS","rotulo":"Art. 40-A","conteudo":"Esta Lei será aplicada a todas as situações previstas no seu art. 5º, independentemente da causa ou da motivação dos atos de violência e da condição do ofensor ou da ofendida. (Artigo acrescido pela Lei nº 14.550, de 19/4/2023)"},{"chave":"art-41","sequencia":52,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":"TÍTULO VII — DISPOSIÇÕES FINAIS","rotulo":"Art. 41.","conteudo":"Aos crimes praticados com violência doméstica e familiar contra a mulher, independentemente da pena prevista, não se aplica a Lei nº 9.099, de 26 de setembro de 1995."},{"chave":"art-42","sequencia":53,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":"TÍTULO VII — DISPOSIÇÕES FINAIS","rotulo":"Art. 42.","conteudo":"O art. 313 do Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal), passa a vigorar acrescido do seguinte inciso IV:\n\n\"Art. 313. .................................................................................\n\n..................................................................................................\n\nIV - se o crime envolver violência doméstica e familiar contra a mulher, nos termos da lei específica, para garantir a execução das medidas protetivas de urgência.\" (NR)"},{"chave":"art-43","sequencia":54,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":"TÍTULO VII — DISPOSIÇÕES FINAIS","rotulo":"Art. 43.","conteudo":"A alínea f do inciso II do art. 61 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), passa a vigorar com a seguinte redação:\n\n\"Art. 61. ....................................................................................\n\n..................................................................................................\n\nII - ............................................................................................\n\n..................................................................................................\n\nf) com abuso de autoridade ou prevalecendo-se de relações domésticas, de coabitação ou de hospitalidade, ou com violência contra a mulher na forma da lei específica;"},{"chave":"art-44","sequencia":55,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":".................................................................................. \"","rotulo":"Art. 44.","conteudo":"O art. 129 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), passa a vigorar com as seguintes alterações:\n\n\"Art. 129. ..................................................................................\n\n..................................................................................................\n\n§ 9º Se a lesão for praticada contra ascendente, descendente, irmão, cônjuge ou companheiro, ou com quem conviva ou tenha convivido, ou, ainda, prevalecendo-se o agente das relações domésticas, de coabitação ou de hospitalidade:\n\nPena - detenção, de 3 (três) meses a 3 (três) anos.\n\n...................................................................................................\n\n§ 11. Na hipótese do § 9º deste artigo, a pena será aumentada de um terço se o crime for cometido contra pessoa portadora de deficiência.\" (NR)"},{"chave":"art-45","sequencia":56,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":"TÍTULO VII — DISPOSIÇÕES FINAIS","rotulo":"Art. 45.","conteudo":"O art. 152 da Lei nº 7.210, de 11 de julho de 1984 (Lei de Execução Penal), passa a vigorar com a seguinte redação:\n\n\"Art. 152. .................................................................................\n\nParágrafo único. Nos casos de violência doméstica contra a mulher, o juiz poderá determinar o comparecimento obrigatório do agressor a programas de recuperação e reeducação.\" (NR)"},{"chave":"art-46","sequencia":57,"caminho":["LEI MARIA DA PENHA","TÍTULO VII — DISPOSIÇÕES FINAIS"],"titulo":"TÍTULO VII — DISPOSIÇÕES FINAIS","rotulo":"Art. 46.","conteudo":"Esta Lei entra em vigor 45 (quarenta e cinco) dias após sua publicação."}]$dados$::jsonb)
    as item(chave text, sequencia integer, caminho text[], titulo text, rotulo text, conteudo text);

